"""Build visitor case studies from the implemented capabilities and measured artifacts."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'docs';OUT.mkdir(exist_ok=True)
def page(name,title,body):
    content=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="/assets/suite.css"><style>main{{max-width:1000px}}pre{{white-space:pre-wrap;overflow-wrap:anywhere}}img{{width:100%;border:1px solid var(--line);border-radius:12px}}li{{margin:10px 0}}h2{{margin-top:32px}}</style></head><body><main><header><a href="/">← F1 GRIDLAB</a><a href="/docs/setup.html">Local setup</a></header><h1>{title}</h1>{body}<footer><p><a href="/docs/validation.html">Validation & Methodology</a></p></footer></main></body></html>'
    (OUT/(name+'.html')).write_text(content,encoding='utf-8')
projects={
 'telemetry':('F1 Telemetry Lab','Compare complete laps without misleading alignment or invented measurements.',[
 'Selects one accurate, non-deleted, non-pit lap per driver. FastF1 nGear and boolean braking are handled explicitly.',
 'Sorts and deduplicates samples, aligns the shared distance interval and uses elapsed time at matching distances. Missing sectors remain unavailable.',
 'Uses circuit metadata for corner names. Select a corner row or the corner selector to highlight the map and traces.',
 'Shows pace by elapsed session time with compound, stint and rain filters. Dry comparable race stints need at least five valid laps for an observed pace slope and uncertainty.'
 ],'Choose 2024 → Silverstone → Q. Keep Russell and Hamilton at their fastest valid laps and select Analyse. Open Corners, select T9, then open Track map. A saved analysis survives other interface changes.',
 'The slope includes fuel, traffic and driver effects. It is not isolated tyre degradation or a physical rubbering-in index. Circuit markers are approximate. Official lap timing and telemetry end delta can differ because distance endpoints and integration differ. First-time session downloads require internet; cached sessions can be reused.'),
 'desktop':('AI Race Engineer','Keep a local coaching display responsive during telemetry, coaching and speech.',[
 'Retains Tkinter with main-thread widget updates and separate bounded telemetry, coaching and audio workers.',
 'Includes start, pause, reset, scenario selection, recorded JSON playback at 1×/2×/4×, reference import and labelled tyre positions.',
 'Bounds remaining tyre state to 0–100% and uses heating/cooling targets. Repeated event/corner warnings have a five-second cooldown with urgency escalation.',
 'Opt-in Windows speech has volume, mute and an optional radio tone. Reset invalidates old coaching and clears queued voice.'
 ],'Open the desktop demo, choose Balanced, press Use illustrative simulator, then Start. Pause and reset. For recorded comparison, load the VER JSON as reference and HAM JSON as run from data/recordings, then Start.',
 'The simulator is illustrative, with no validated vehicle physics or game connection. Recorded tyre channels are optional and unknown channels stay unavailable. Guidance requires overlapping reference distance; lateral guidance additionally requires X/Y in the same coordinate system. Voice depends on installed Windows voices. The default coaching engine is deterministic rules.'),
 'replay':('AI Replay Engineer','Replay real timestamps and measure what differs from a reference.',[
 'Single-lap recordings provide timestamp, distance, speed, normalized pedals and gear. Browser interpolation matches the server reference.',
 'Cumulative time delta uses elapsed time at matching distance. Braking uses the interpolated pedal threshold crossing, with measured early/late metres.',
 'Session identifiers and increasing sequence numbers reject stale frames. Reset cancels the active AI request and clears gauges, plots, radio and voice.',
 'One asynchronous coaching request runs per session. Browser voice is opt-in, prioritized, bounded, cancellable and adjustable.'
 ],'Start the matched-reference demo at 4×: delta remains near zero. Reset, choose Late braking and resume to see measured coaching. Import silverstone-2024-ver.json as reference, then silverstone-2024-ham.json as recorded run for a sourced example.',
 'The default speed profile is generated, not an official pole lap. Official sample files are labelled separately. Braking thresholds and sample rate limit measurement precision. X/Y guidance is unavailable without position channels in both recordings. Live UDP is deferred; the offline parser only accepts the tested F1 23 v1 telemetry packet.'),
 'summariser':('Race Summariser','Produce a debrief that keeps supplied evidence separate from generated explanation.',[
 'Uses one event taxonomy across timeline filters and reports, including pit-cycle gains and retirement inheritance.',
 'Validated JSON imports persist in SQLite. Omitted winners, dates, lap counts and events remain unknown.',
 'Shipped race examples use refreshed FastF1 timing and concise sourced FIA report annotations. Selected timelines are explicitly incomplete.',
 'Renders text safely and exports Markdown. Optional local AI identifies its actual engine and fallback reason.'
 ],'Select 2024 Italian Grand Prix, choose the PIT CYCLE GAIN timeline filter, then Generate debrief. The strategy section includes Norris’s undercut. Export Markdown. Import the minimal example in the setup guide to check unknown-field handling.',
 'A timeline is a selected set of supplied annotations, not a complete event detector. Stints use timing-feed lap groups. Generated interpretation may need source checking; the facts-only template is the deterministic default.'),
 'predictor':('Race Result Predictor','Evaluate a model against simple baselines and make strategy assumptions inspectable.',[
 'Loads Jolpica race and qualifying grids with pagination, timeouts, caching and nested-response parsing.',
 'Fits preprocessing and models on completed 2018–2023 races. Selects depth in early 2024, calibrates probabilities in late 2024 and evaluates 2025 once.',
 'Computes form from completed prior races. Both teammates are aggregated before the constructor rolling window, preventing same-race result leakage.',
 'Scores the complete available classified grid and offers a separate one-stop/two-stop scenario calculator with displayed pace, degradation, pit laps and pit loss.'
 ],'Generate a full-grid score, inspect its qualifying baseline, then open Strategy what-if. Change pit loss or degradation to see the scenario times change. Evaluation & coverage exposes saved metadata and source cutoff.',
 'On 2025, model position MAE is 3.388 versus qualifying baseline 3.338; probability Brier is 0.1743 versus simple baseline 0.1676 (lower is better). The model does not beat either baseline. Training-season scores are exploratory, and 2024 was used for selection/calibration. These are not live forecasts. Scenario results do not change ML probabilities. Spain 2025 has 19 entries in the source classification; an absent entry is not invented.'),
 'chatbot':('F1 Knowledge Assistant','Answer supported F1 questions with deterministic statistics and inspectable sources.',[
 'Parses season, intent, driver, team and race. Unsupported years or comparisons produce a clear unavailable-data answer.',
 'Includes 173 races and 3,458 classified entries from 2018–2025, final-season standings, race and qualifying results.',
 'Pairs teammate qualifying only within the same team/session, shows counts and exclusions, and exports the source sessions.',
 'Uses four versioned 2026 regulation summaries and three sourced circuit profiles. Topic-constrained retrieval similarity is never shown as answer confidence.'
 ],'Ask “Who won Monaco in 2024?” or “Compare Hamilton and Russell teammate qualifying in 2024”. Open source sessions. Then ask about 2030 to see the coverage boundary. Topics & coverage opens with the keyboard; Escape closes it.',
 'Circuit characteristics currently cover Silverstone, Monza and Monaco. Regulations are selected summaries with issue date, section, source and retrieval date, not the whole rulebook. Historical numeric coverage ends in 2025. The optional Ollama explanation is labelled separately from deterministic answers.')
}
for name,(title,problem,changes,demo,limits) in projects.items():
    body=f'<p class="muted">{html.escape(problem)}</p><img src="/assets/previews/{name}.png" alt="{title} verified application preview"><h2>Engineering approach</h2><ul>'+''.join('<li>'+html.escape(c)+'</li>' for c in changes)+f'</ul><h2>Try the demo</h2><p>{html.escape(demo)}</p><h2>Evidence and limits</h2><p>{html.escape(limits)}</p>'
    if name!='desktop':body+=f'<p><a href="/demo/{name}">Open local demo →</a></p>'
    if name in ('replay','desktop'):body+='<p>Recorded samples: <a download href="/recordings/silverstone-2024-ver.json">VER reference</a> · <a download href="/recordings/silverstone-2024-ham.json">HAM run</a></p>'
    page(name,title,body)
setup='''<p>This suite is designed for local demonstrations. The tested environment is Windows with Python 3.14. Each application retains its original framework.</p>
<h2>Install and launch</h2><ol><li>Open SETUP_PORTFOLIO.bat in the project folder. It creates a private .venv and installs requirements-tested.txt.</li><li>Open START_PORTFOLIO.bat. It checks service readiness and opens this portfolio.</li><li>Use a project’s demo button. Open desktop demo starts the Tkinter app.</li></ol>
<p>Equivalent terminal commands, from the project root:</p><pre>python -m venv .venv
.venv\\Scripts\\python.exe -m pip install -r requirements-tested.txt
.venv\\Scripts\\python.exe launcher.py start
.venv\\Scripts\\python.exe launcher.py status
.venv\\Scripts\\python.exe launcher.py stop</pre>
<p>The stop command terminates only processes owned by this launcher. An occupied, unready port is reported without killing the other process. Startup logs live in .runtime. For an import error, reinstall the tested dependencies in the same interpreter; for an occupied port, close the conflicting local service and retry.</p>
<h2>Documented ports</h2><table><thead><tr><th>Application</th><th>Local port</th></tr></thead><tbody><tr><td>Portfolio</td><td>5501</td></tr><tr><td>Summariser</td><td>8000</td></tr><tr><td>Replay Engineer</td><td>8001</td></tr><tr><td>Knowledge Assistant</td><td>8002</td></tr><tr><td>Predictor</td><td>8501</td></tr><tr><td>Telemetry Lab</td><td>8502</td></tr></tbody></table>
<h2>Offline operation and optional AI</h2><p>Shipped historical datasets, model artifacts, recorded examples, facts-only reports and deterministic coaching operate locally. Telemetry Lab needs a first download for uncached sessions. The default Silverstone 2024 qualifying session is cached in this build. Optional Ollama runs locally on its standard service port and must already have the selected model installed. The application reports a deterministic fallback on timeout or unavailability. No key is needed for the default workflows.</p>
<h2>Recording contract</h2><p>UTF-8 JSON object: schema_version 1, a provenance object and 2–100,000 samples. A file contains one lap. Timestamps (seconds) and distance (metres) must strictly increase; timestamps are normalized to the first sample. Speed is km/h (0–500); throttle and brake are 0–1; gear is an integer from −1 to 8. Optional x/y must share a coordinate system between recordings. Optional tire_temps and tire_wear maps use FL, FR, RL, RR; the latter means percent remaining, 0–100. Unknown channels are omitted. The browser accepts up to 12 MB per file and 15 MB combined after normalization.</p>
<pre>{"schema_version":1,"provenance":{"mode":"recorded","source":"Your supplied lap","position_units":"metres"},"samples":[{"timestamp":0,"distance":0,"speed":100,"throttle":1,"brake":0,"gear":3},{"timestamp":1,"distance":27.8,"speed":100,"throttle":1,"brake":0,"gear":3}]}</pre>
<p>Load VER as reference and HAM as run for the shipped Silverstone pair. The run’s distance must fit inside the reference range. Braking onsets are paired conservatively within 100 metres, with mutual-nearest matching when both recordings are available; unmatched events remain unavailable. Position units in these FastF1 examples are decimetres, explicitly labelled; they are not metre-valued GPS coordinates.</p>
<h2>Minimal race import</h2><pre>{"race_id":"my_race","name":"My race","circuit":"My circuit"}</pre><p>Optional fields include date, laps, winner, podium, key_timeline, strategy_stints and sources. Use Download import template in the app. Unknown fields and malformed values are rejected. Imports are saved in projects/race-summariser/race_summariser/backend/races.sqlite3; back up that file before moving installations.</p>
<h2>Reproduce data and evaluation</h2><pre>.venv\\Scripts\\python.exe projects/race-result-predictor/race_result_predictor/data_pipeline.py
.venv\\Scripts\\python.exe projects/race-result-predictor/race_result_predictor/model_trainer.py
.venv\\Scripts\\python.exe scripts/export_recordings.py
.venv\\Scripts\\python.exe scripts/export_race_fixtures.py</pre><p>Network requests are cached in data/cache. Dataset cutoff and retrieval time are recorded in data/coverage.json; model metadata records train/selection/calibration/test ranges, feature definitions and measured baselines. Load only trusted local model artifacts.</p>
<h2>Run checks</h2><pre>.venv\\Scripts\\python.exe -B -m unittest discover -s tests -v
node tests/test_frontend.cjs
.venv\\Scripts\\python.exe -B tests/soak.py</pre><p>The soak needs Replay Engineer running from the launcher and a Windows desktop session. It lasts 30 real minutes and writes .implementation/soak.json. Keep the app services running during the test. Shorter SOAK_SECONDS values are useful for smoke tests but do not satisfy the 30-minute acceptance check.</p>'''
page('setup','Local setup & reproducibility',setup)
meta=json.loads((ROOT/'projects/race-result-predictor/race_result_predictor/model_metadata.json').read_text())
soak=json.loads((ROOT/'.implementation/soak.json').read_text()) if (ROOT/'.implementation/soak.json').exists() else {}
first=json.loads((ROOT/'.implementation/soak-first-complete.json').read_text()) if (ROOT/'.implementation/soak-first-complete.json').exists() else {}
soak_text=f"Instrumented stability run: {soak.get('elapsed_seconds',0):.1f} seconds, {soak.get('frames',0):,} replay frames, {len(soak.get('failures',[]))} failures. "+('Complete.' if soak.get('complete') else 'In progress; not yet accepted as a completed final run.')
page('validation','Validation & Methodology — 12 October 2026',f'''<p>Results below describe this local build and supplied data.</p><h2>Measured checks</h2><ul><li>Telemetry: official cached 2024 Silverstone qualifying loaded and analysed; 18 circuit-metadata corners. Regression fixtures recover zero delta for identical laps and a known one-second offset.</li><li>45 Python regression checks plus JavaScript reset, stale-response and recording-size checks passed after fixes. The independent review identified two chatbot defects, both fixed, but ended early at its usage limit; a complete independent sign-off is not claimed. The final test log is retained in .implementation/regression.log.</li><li>Seeded 10,000-frame simulator run: 88.1–112.3°C, 85–100% tyre remaining, bounded history and cooldown entries.</li><li>{html.escape(soak_text)} Earlier stability run completed {first.get('elapsed_seconds',0):.1f} seconds with {len(first.get('failures',[]))} errors.</li><li>All six web surfaces measured at 390, 768 and 1440 pixels without page-wide horizontal overflow. Desktop primary controls remain visible at its 390-pixel minimum client width; remaining content scrolls vertically.</li><li>Browser workflows include analysis, full-grid scoring, strategy changes, recorded replay/reset, unsupported questions, qualifying comparisons, keyboard dialogs and an incomplete import containing HTML displayed as text.</li></ul><p>The 30-minute stability run preceded the final chatbot, braking-association and input-validation fixes. Those fixes passed targeted regression and browser checks; the unchanged simulator and queue lifecycle were covered by the soak. No second full independent review was completed.</p><h2>Historical model performance</h2><table><thead><tr><th>2025 held-out metric</th><th>Model</th><th>Baseline</th></tr></thead><tbody><tr><td>Classified position MAE</td><td>{meta['evaluation_2025']['mae']:.4f}</td><td>{meta['qualifying_order_baseline']['mae']:.4f}</td></tr><tr><td>Top-10 probability Brier</td><td>{meta['evaluation_2025']['brier_score']:.4f}</td><td>{meta['simple_probability_baseline']['brier_score']:.4f}</td></tr></tbody></table><p>Lower is better. The model underperforms both baselines. Accuracy claims are limited to this completed backtest, not future races.</p><h2>Limits</h2><p>Live game UDP and public deployment are deferred. Optional live LLM generation and audible output across every browser/device remain environment-dependent. This is a local portfolio demonstration, not a production race-control system or calibrated vehicle model.</p><h2>Sources</h2><p><a href="https://github.com/jolpica/jolpica-f1/blob/main/docs/README.md">Jolpica API documentation</a> · <a href="https://docs.fastf1.dev/">FastF1 documentation</a> · <a href="https://www.fia.com/regulation/category/110/technical-regulations">FIA regulations catalogue</a>. Each race, regulation and circuit record includes its specific source.</p>''')
print('Built',len(projects)+2,'documentation pages')
